const KEY='baoDumplingOrders',PASSWORD_KEY='baoDumplingManagerPassword',ADJUSTMENTS_KEY='baoDumplingAdjustments',AUDIT_KEY='baoDumplingAudit';
const catalog=[['A1','包子','素包子','Bao végétarien',1],['A2','包子','猪肉包','Bao porc',1.25],['A3','包子','牛肉包','Bao bœuf',1.5],['A4','包子','香煎包','Bao poêlé',1.75],['B1','饺子','白面水饺','Raviolis nature',4],['B2','饺子','菠菜水饺','Raviolis aux épinards',5],['B3','饺子','胡萝卜水饺','Raviolis aux carottes',5],['B4','饺子','三色水饺','Assortiment trois couleurs',5],['C1','粥品','红豆粥','Congee aux haricots rouges',3.5],['C2','粥品','绿豆粥','Congee aux haricots mungo',3.5],['C3','粥品','小米粥','Congee au millet',3.5],['C4','粥品','八宝粥','Congee huit trésors',3.8],['C5','粥品','皮蛋瘦肉粥','Congee au porc et œuf de cent ans',3.8]].map(([code,category,dish,fr,price])=>({code,category,dish,fr,price}));
const fillings=[['','—'],['韭菜鸡蛋','Poireau et œuf'],['鲜肉','Porc'],['牛肉','Bœuf']];
const styles={包子:[['','—'],['清蒸','Vapeur'],['煎包','Poêlé']],饺子:[['','—'],['水煮','À l’eau'],['清蒸','Vapeur'],['煎饺','Poêlés']],粥品:[['','—']]};
const money=value=>`${Number(value||0).toFixed(2).replace('.',',')} €`;
const today=()=>new Date().toDateString(),month=()=>new Date().toISOString().slice(0,7);
const allOrders=()=>JSON.parse(localStorage.getItem(KEY)||'[]');
const adjustments=()=>JSON.parse(localStorage.getItem(ADJUSTMENTS_KEY)||'[]');
const orderTotal=order=>order.items.reduce((sum,item)=>sum+Number(item.price||0)*Math.max(1,Number(item.qty)||1),0);
const paidOrder=order=>order.status==='paid'||order.status==='done';
const audit=(action,details)=>{const records=JSON.parse(localStorage.getItem(AUDIT_KEY)||'[]');records.push({time:new Date().toLocaleString('fr-FR'),action,details});localStorage.setItem(AUDIT_KEY,JSON.stringify(records.slice(-120)));};
const renderAudit=()=>{const holder=document.querySelector('#audit-list');if(!holder)return;const records=JSON.parse(localStorage.getItem(AUDIT_KEY)||'[]').slice(-8).reverse();holder.innerHTML=records.length?records.map(record=>`<div><strong>${record.action}</strong> · ${record.details}<br><small>${record.time}</small></div>`).join(''):'暂无管理记录 / Aucun historique';};
function statusLabel(status){return status==='paid'?['已收款','Encaissée']:status==='done'?['已完成','Terminée']:status==='cancelled'?['已取消','Annulée']:['待处理','À préparer']}
function adjustmentTotal(filter){return adjustments().filter(filter).reduce((sum,item)=>sum+Number(item.amount||0),0)}
let adminUnlocked=false,editingId=null,pendingAdminAction=null;
function render(){const orders=allOrders(),daily=orders.filter(order=>order.day===today()),monthly=orders.filter(order=>order.month===month());const revenue=daily.filter(paidOrder).reduce((sum,order)=>sum+orderTotal(order),0)+adjustmentTotal(item=>item.day===today());const monthRevenue=monthly.filter(paidOrder).reduce((sum,order)=>sum+orderTotal(order),0)+adjustmentTotal(item=>item.month===month());document.querySelector('#revenue').textContent=money(revenue);document.querySelector('#month-revenue').textContent=money(monthRevenue);document.querySelector('#order-count').textContent=daily.filter(order=>order.status!=='cancelled').length;document.querySelector('#pending-count').textContent=daily.filter(order=>order.status==='pending').length;const holder=document.querySelector('#orders'),empty=document.querySelector('#empty-state');holder.innerHTML='';empty.hidden=daily.length>0;[...daily].reverse().forEach(order=>{const [zh,fr]=statusLabel(order.status);const active=order.status!=='cancelled';const card=document.createElement('article');card.className='order';card.innerHTML=`<div class="order-head"><div><h3>${order.id}</h3><small>${order.time}</small></div><span class="status ${order.status}">${zh} · ${fr}</span></div><div class="items">${order.items.map(item=>`${item.code?`${item.code} · `:''}${item.dish} · ${item.fr}${item.filling?` · ${item.filling} / ${item.fillingFr} · ${item.style} / ${item.styleFr}`:''}${Number(item.qty||1)>1?` × ${item.qty}`:''}`).join('<br>')}</div><div class="order-foot"><strong>${money(orderTotal(order))}</strong><div class="actions">${order.status==='pending'?'<button class="primary" data-action="paid">收款 · Encaisser</button>':''}${order.status!=='done'&&active?'<button data-action="done">完成 · Terminer</button>':''}${active?'<button data-action="edit">修改 · Modifier</button><button class="danger-action" data-action="cancel">取消订单 · Annuler</button>':''}</div></div>`;card.querySelectorAll('button').forEach(button=>button.onclick=()=>handleAction(order.id,button.dataset.action));holder.append(card)})}
function cancelOrder(id){const all=allOrders(),order=all.find(item=>item.id===id);if(!order||!confirm(`确认取消 ${order.id}？取消后会立刻扣除 ${money(orderTotal(order))}。\nAnnuler cette commande ?`))return;const wasPaid=order.status==='paid'||order.status==='done';order.status='cancelled';if(wasPaid){order.refundAmount=orderTotal(order);order.refundedAt=new Date().toISOString()}localStorage.setItem(KEY,JSON.stringify(all));audit(wasPaid?'退款取消':'取消订单',`${order.id} · -${money(orderTotal(order))}`);render()}
function handleAction(id,action){if(action==='edit'){editingId=id;return requireAdmin(()=>openEditor(id))}if(action==='cancel')return requireAdmin(()=>cancelOrder(id));const all=allOrders(),order=all.find(item=>item.id===id);if(!order)return;order.status=action==='paid'?'paid':'done';localStorage.setItem(KEY,JSON.stringify(all));audit(action==='paid'?'收款':'完成',order.id);render()}
function selectOptions(values,current){return values.map(([value,label])=>`<option value="${value}" ${value===current?'selected':''}>${value?`${value} · ${label}`:'—'}</option>`).join('')}
function productOptions(current){return catalog.map(product=>`<option value="${product.code}" ${product.code===current?'selected':''}>${product.code} · ${product.dish} · ${product.fr}</option>`).join('')}
function normaliseItem(item){const product=catalog.find(entry=>entry.code===item.code||entry.dish===item.dish)||catalog[0];return {...product,...item,code:item.code||product.code,category:item.category||product.category,fr:item.fr||product.fr,price:Number(item.price||product.price),qty:Math.max(1,Number(item.qty)||1)}}
function line(item){const data=normaliseItem(item),row=document.createElement('div');row.className='line-item';row.innerHTML=`<div><label>菜品 / Produit</label><select class="product">${productOptions(data.code)}</select></div><div><label>馅料 / Farce</label><select class="filling">${selectOptions(fillings,data.filling||'')}</select></div><div><label>做法 / Cuisson</label><select class="style">${selectOptions(styles[data.category],data.style||'')}</select></div><div><label>数量</label><input class="qty" type="number" min="1" value="${data.qty}"></div><button class="remove" type="button">删除</button>`;const product=row.querySelector('.product'),style=row.querySelector('.style'),filling=row.querySelector('.filling');let initial=true;function adapt(){const chosen=catalog.find(entry=>entry.code===product.value),chosenStyle=initial?(data.style||''):'';if(chosen.category==='粥品'){filling.value='';filling.disabled=true;style.innerHTML=selectOptions(styles.粥品,'');style.disabled=true}else{filling.disabled=false;style.disabled=false;style.innerHTML=selectOptions(styles[chosen.category],chosenStyle)}initial=false}product.onchange=adapt;adapt();row.querySelector('.remove').onclick=()=>row.remove();return row}
const editor=document.querySelector('#order-dialog'),editItems=document.querySelector('#edit-items');
function openEditor(id){const order=allOrders().find(item=>item.id===id);if(!order)return;editingId=id;document.querySelector('#order-editor-title').textContent=`修改订单 ${order.id} · Modifier`;editItems.innerHTML='';order.items.map(normaliseItem).forEach(item=>editItems.append(line(item)));editor.showModal()}
function collectLines(){return [...editItems.querySelectorAll('.line-item')].map(row=>{const product=catalog.find(item=>item.code===row.querySelector('.product').value),filling=row.querySelector('.filling').value,style=row.querySelector('.style').value;return {...product,filling,fillingFr:fillings.find(item=>item[0]===filling)?.[1]||'',style,styleFr:(styles[product.category]||[]).find(item=>item[0]===style)?.[1]||'',qty:Math.max(1,Number(row.querySelector('.qty').value)||1)}})}
document.querySelector('#add-item').onclick=()=>editItems.append(line(catalog[0]));
document.querySelector('#save-order').onclick=()=>{const items=collectLines();if(!items.length){alert('请保留至少一个菜品 / Gardez au moins un produit');return}const all=allOrders(),order=all.find(item=>item.id===editingId);if(!order)return;order.items=items;order.total=orderTotal(order);localStorage.setItem(KEY,JSON.stringify(all));audit('修改订单',`${order.id} · ${money(order.total)}`);editor.close();render()};
document.querySelector('#cancel-order').onclick=()=>{editor.close();cancelOrder(editingId)};
const dialog=document.querySelector('#manage-dialog'),input=document.querySelector('#manager-password'),label=document.querySelector('#password-label'),passwordAction=document.querySelector('#password-action'),passwordSection=document.querySelector('#password-section'),adminSection=document.querySelector('#admin-section');
function openManage(){const hasPassword=Boolean(localStorage.getItem(PASSWORD_KEY));input.value='';input.autocomplete=hasPassword?'current-password':'new-password';label.textContent=hasPassword?'输入管理密码 · Mot de passe':'设置管理密码 · Créer un mot de passe';passwordAction.textContent=hasPassword?'解锁 · Déverrouiller':'保存密码 · Enregistrer';passwordSection.hidden=false;adminSection.hidden=true;dialog.showModal()}
function requireAdmin(callback){if(adminUnlocked){callback();return}pendingAdminAction=callback;openManage()}
passwordAction.onclick=()=>{const value=input.value.trim();if(!value){alert('请输入密码 / Saisissez un mot de passe');return}const stored=localStorage.getItem(PASSWORD_KEY);if(!stored){localStorage.setItem(PASSWORD_KEY,value)}else if(value!==stored){alert('密码不正确 / Mot de passe incorrect');return}adminUnlocked=true;passwordSection.hidden=true;adminSection.hidden=false;input.value='';renderAudit();if(pendingAdminAction){const action=pendingAdminAction;pendingAdminAction=null;dialog.close();action()}};
document.querySelector('#add-adjustment').onclick=()=>{const amount=Number(document.querySelector('#adjust-amount').value),reason=document.querySelector('#adjust-reason').value.trim();if(!amount||!reason){alert('请输入金额与原因 / Saisissez le montant et le motif');return}const now=new Date(),list=adjustments();list.push({id:`ADJ-${now.getTime()}`,day:today(),month:month(),time:now.toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'}),amount,reason});localStorage.setItem(ADJUSTMENTS_KEY,JSON.stringify(list));audit('营业额调整',`${money(amount)} · ${reason}`);document.querySelector('#adjust-amount').value='';document.querySelector('#adjust-reason').value='';renderAudit();render()};
document.querySelector('#reset-month').onclick=()=>{if(!confirm('确认将本月营业额和订单归零？此操作无法恢复。\nConfirmer la remise à zéro du mois ?'))return;localStorage.setItem(KEY,JSON.stringify(allOrders().filter(order=>order.month!==month())));localStorage.setItem(ADJUSTMENTS_KEY,JSON.stringify(adjustments().filter(item=>item.month!==month())));audit('本月归零',month());dialog.close();render()};
document.querySelector('#manage').onclick=openManage;window.addEventListener('storage',render);setInterval(render,2500);render();
